bool W3DFontLibrary::loadFontData(GameFont *font)
{
	FontCharsClass *fontChar;

	if (font == 0)
		return false;

	if ((unsigned int)font->pointSize > 100)
		fontChar = 0;
	else
		fontChar = (FontCharsClass *)Rva0009017D(font->nameString.str(), font->pointSize, font->bold ? true : false, font->rasterScale);

	if (fontChar == 0)
		return false;

	font->fontData = fontChar;
	font->height = fontChar->Get_Char_Height();

	FontCharsClass *unicodeFontChar;
	GlobalLanguage *language = TheGlobalLanguageData;
	if (language)
		unicodeFontChar = (FontCharsClass *)Rva0009017D(language->m_unicodeFontName.str(), font->pointSize, font->bold ? true : false, font->rasterScale);
	else
		unicodeFontChar = (FontCharsClass *)Rva0009017D("Arial Unicode MS", font->pointSize, font->bold ? true : false, font->rasterScale);

	if (unicodeFontChar)
		fontChar->AlternateUnicodeFont = unicodeFontChar;

	return true;
}
